        let bInputs = Inputs.vectors(H.Vector.self, seed: 0xD172_F93D_7E01_7967)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0xD172_FA3D_7E01_7B1A)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0xD172_FB3D_7E01_7CCD)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0x55B1_F0AC_ADFD_52E8
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
